import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { IncomingForm } from 'formidable';
import { unstable_getServerRequest } from 'next/server';

export const config = {
  api: { bodyParser: false }
};

export async function POST(req) {
  // Get a Node.js HTTP IncomingMessage
  const nodeReq = unstable_getServerRequest(req);

  // Parse the multipart form using formidable
  const form = new IncomingForm();
  return new Promise((resolve) => {
    form.parse(nodeReq, async (err, fields, files) => {
      if (err) {
        resolve(
          new Response(JSON.stringify({ error: 'Form parsing error: ' + err.message }), { status: 400 })
        );
        return;
      }

      const gymId = fields.gym_id;
      const file = files.profilePicture;
      if (!gymId) {
        resolve(new Response(JSON.stringify({ error: 'gym_id is required' }), { status: 400 }));
        return;
      }
      if (!file) {
        resolve(new Response(JSON.stringify({ error: 'profilePicture file is required' }), { status: 400 }));
        return;
      }

      const fileData = await fs.promises.readFile(file.filepath);

      const s3 = new S3Client({
        region: 'auto',
        endpoint: process.env.R2_ENDPOINT,
        credentials: {
          accessKeyId: process.env.R2_ACCESS_KEY_ID,
          secretAccessKey: process.env.R2_SECRET_ACCESS_KEY,
        },
      });

      try {
        await s3.send(
          new PutObjectCommand({
            Bucket: process.env.R2_BUCKET,
            Key: gymId,
            Body: fileData,
            ContentType: file.mimetype || 'application/octet-stream',
          })
        );
        resolve(new Response(JSON.stringify({ success: true, key: gymId }), { status: 200 }));
      } catch (uploadError) {
        resolve(
          new Response(JSON.stringify({ error: 'Upload failed: ' + uploadError.message }), { status: 500 })
        );
      }
    });
  });
}
